clear; clc; close all;

%%\ 1. SETTINGS

N_values = [5e5, 1e6, 2e6, 4e6, 7e6, 1e7, 1.3e7];

sigma = 1/6.3;
gamma = 1/10;

mu_dem = 1/(62.07*365);

models(1).name = 'Basic SEIR';
models(1).mu = 0;

models(2).name = 'Demographic SEIR';
models(2).mu = mu_dem;

n_starts = 10;

rng(1);

%%\ 2. LOAD DATA

[report_date, cum_obs] = load_cases(); %[output:13551f98]

t = days(report_date - report_date(1));
dt = diff(t);

obs_per_day = diff(cum_obs) ./ dt;

nm = numel(models);
nN = numel(N_values);

%%\ 3. STORAGE

beta_results = zeros(nN, nm);
R0_results   = zeros(nN, nm);
rmse_results = zeros(nN, nm);

%%\ 4. REFIT EACH MODEL FOR EACH N

for j = 1:nN %[output:group:290813d8]

    N = N_values(j);

    fprintf('\nTesting N = %g\n', N); %[output:9856e45d] %[output:835ced6a] %[output:92652ae6] %[output:9dec3917] %[output:9462d5d1] %[output:5057b0be] %[output:9c2295d0]

    for m = 1:nm

        theta = fit_model( ...
            t, cum_obs, N, models(m).mu, ...
            sigma, gamma, n_starts);

        beta_results(j,m) = theta(1);

        R0_results(j,m) = theta(1) / ...
            (gamma + models(m).mu);

        C = simulate_cum( ...
            theta, t, N, models(m).mu, ...
            sigma, gamma);

        pred_per_day = diff(C) ./ dt;

        rmse_results(j,m) = sqrt(mean( ...
            (pred_per_day - obs_per_day).^2));

        fprintf('  %s: beta = %.5f, R0 = %.5f, RMSE = %.3f\n', ... %[output:844b9a9d] %[output:4a297531] %[output:4c824a0a] %[output:98041de6] %[output:328f1e54] %[output:560da9a8] %[output:893c8ee1]
            models(m).name, ... %[output:844b9a9d] %[output:4a297531] %[output:4c824a0a] %[output:98041de6] %[output:328f1e54] %[output:560da9a8] %[output:893c8ee1]
            beta_results(j,m), ... %[output:844b9a9d] %[output:4a297531] %[output:4c824a0a] %[output:98041de6] %[output:328f1e54] %[output:560da9a8] %[output:893c8ee1]
            R0_results(j,m), ... %[output:844b9a9d] %[output:4a297531] %[output:4c824a0a] %[output:98041de6] %[output:328f1e54] %[output:560da9a8] %[output:893c8ee1]
            rmse_results(j,m)); %[output:844b9a9d] %[output:4a297531] %[output:4c824a0a] %[output:98041de6] %[output:328f1e54] %[output:560da9a8] %[output:893c8ee1]

    end
end %[output:group:290813d8]

%%\ 5. RESULTS TABLE

sensitivity_results = table( ...
    N_values', ...
    beta_results(:,1), ...
    beta_results(:,2), ...
    R0_results(:,1), ...
    R0_results(:,2), ...
    rmse_results(:,1), ...
    rmse_results(:,2), ...
    'VariableNames', { ...
    'N', ...
    'BasicSEIR_beta', ...
    'DemographicSEIR_beta', ...
    'BasicSEIR_R0', ...
    'DemographicSEIR_R0', ...
    'BasicSEIR_RMSE', ...
    'DemographicSEIR_RMSE'});

disp(sensitivity_results); %[output:863c7fe1]

%%\ 6. SAVE

if ~isfolder('results')
    mkdir('results');
end

writetable(sensitivity_results, ...
    fullfile('results', 'N_sensitivity.csv'));

%%\ 7. PLOT R0

fig1 = figure('Color','w'); %[output:35bdf682]

plot(N_values, R0_results(:,1), '-o'); %[output:35bdf682]
hold on; %[output:35bdf682]
plot(N_values, R0_results(:,2), '-s'); %[output:35bdf682]

xlabel('Assumed at-risk population N'); %[output:35bdf682]
ylabel('R_0'); %[output:35bdf682]
legend({models.name}, 'Location', 'best'); %[output:35bdf682]
title('Sensitivity of R_0 to assumed population size'); %[output:35bdf682]
grid on; %[output:35bdf682]

saveas(fig1, ... %[output:group:240541f6] %[output:35bdf682]
    fullfile('results', 'N_sensitivity_R0.png')); %[output:group:240541f6] %[output:35bdf682]

%%\ 8. PLOT BETA

fig2 = figure('Color','w'); %[output:6b7dd10c]

plot(N_values, beta_results(:,1), '-o'); %[output:6b7dd10c]
hold on; %[output:6b7dd10c]
plot(N_values, beta_results(:,2), '-s'); %[output:6b7dd10c]

xlabel('Assumed at-risk population N'); %[output:6b7dd10c]
ylabel('\beta'); %[output:6b7dd10c]
legend({models.name}, 'Location', 'best'); %[output:6b7dd10c]
title('Sensitivity of fitted \beta to assumed population size'); %[output:6b7dd10c]
grid on; %[output:6b7dd10c]

saveas(fig2, ... %[output:group:7543bf64] %[output:6b7dd10c]
    fullfile('results', 'N_sensitivity_beta.png')); %[output:group:7543bf64] %[output:6b7dd10c]

